module pulse_detect(
    input clk, 
    input rst_n, 
    input data_in,
    output reg data_out
);
// Define parameters for states
parameter INITIAL = 3'b000;
parameter WAIT_FOR_ONE = 3'b001;
parameter WAIT_FOR_ZERO = 3'b010;
parameter PULSE_END = 3'b011;
// Declare state register
reg [2:0] state;
// Declare next state register
reg [2:0] next_state;
// Combinational logic for state transitions and output generation
always @(*) begin
    case(state)
        INITIAL: begin
            if(~rst_n) begin
                next_state = INITIAL;
                data_out = 1'b0;
            end else if(data_in == 1'b1) begin
                next_state = WAIT_FOR_ZERO;
                data_out = 1'b0;
            end else begin
                next_state = INITIAL;
                data_out = 1'b0;
            end
        end

        WAIT_FOR_ZERO: begin
            if(~rst_n) begin
                next_state = INITIAL;
                data_out = 1'b0;
            end else if(data_in == 1'b0) begin
                next_state = PULSE_END;
                data_out = 1'b1;
            end else begin
                next_state = WAIT_FOR_ZERO;
                data_out = 1'b0;
            end
        end

        PULSE_END: begin
            if(~rst_n) begin
                next_state = INITIAL;
                data_out = 1'b0;
            end else if(data_in == 1'b0) begin
                next_state = INITIAL;
                data_out = 1'b0;
            end else begin
                next_state = WAIT_FOR_ZERO;
                data_out = 1'b0;
            end
        end

        default: begin
            next_state = INITIAL;
            data_out = 1'b0;
        end
    endcase
end
// Sequential logic for state updates
always @(posedge clk or negedge rst_n) begin
    if(~rst_n) begin
        state <= INITIAL;
    end else begin
        state <= next_state;
    end
end
endmodule
